          "params": {
            "service": "worker"
          }
        }
      ]
    },
    {
      "service": "sync-job",
      "kind": "runtime_fault",
      "mechanism": "Sync-job process is stuck in a state where it incorrectly reports disk quota errors despite sufficient disk space.",
      "supporting": ["E16", "E3", "E6", "E32"],
